"use client";

import {
  RiImageAddLine,
  RiMore2Line,
  RiCheckLine,
  RiCloseLine,
  RiDownloadLine,
  RiGalleryLine,
  RiSparklingLine,
} from "@remixicon/react";
import { motion, useReducedMotion } from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";
import { Dialog, Heading, Modal, ModalOverlay } from "react-aria-components";
import { Button } from "../../base/buttons/button";
import { IconButton } from "../../base/buttons/icon-button";
import { PillTab, PillTabList } from "../../base/tabs/pill-tab";
import { cx } from "../../utils/cx";
import {
  AgentWorkspace,
  WorkspacePanelActions,
  workspaceUserMessageClasses,
  type AgentWorkspaceAppearance,
} from "./agent-workspace";
import { GeneratedImageCard } from "../image-generation/generated-image-card";
import { ConversationFeedback } from "../conversation/conversation-feedback";
import { type GalleryImage, IMAGE_GALLERY } from "./image-gallery-data";

export interface ImageGenerationResult {
  /** Optional gallery rendition of the same result. */
  gallerySrc?: string;
  src: string;
  alt?: string;
}
export interface AIImageGenerationTemplateProps {
  /** Return the URL of your generated image. The default is a timed, local example. */
  onGenerate?: (
    prompt: string,
    options: { signal: AbortSignal; style: string },
  ) => Promise<ImageGenerationResult>;
  gallery?: GalleryImage[];
  workspace?: AgentWorkspaceAppearance;
  examplePrompt?: string;
  exampleResult?: ImageGenerationResult;
  /** Optional gallery filtering for host applications. */
  enableGallerySearch?: boolean;
  autoRun?: boolean;
  /** Enable selectable Styles thumbnails. The reference default is an empty “Style presets” panel. */
  enableStylePresets?: boolean;
  contained?: boolean;
  className?: string;
}
const PROMPT =
  "Create a vintage editorial illustration of a footballer dribbling in a blue and white striped kit against a blue background.";
const RESULT = {
  src: "/ai-chat/generated-footballer-preview.webp",
  gallerySrc: "/ai-chat/generated-footballer.jpg",
  alt: "Vintage illustration of a footballer in a striped kit against a blue background",
};
const STYLES = [
  "Editorial",
  "Photography",
  "Illustration",
  "3D render",
  "Screenprint",
  "Cinematic",
];

export function AIImageGenerationTemplate({
  onGenerate,
  gallery = IMAGE_GALLERY,
  workspace,
  examplePrompt = PROMPT,
  exampleResult = RESULT,
  enableGallerySearch = false,
  autoRun = true,
  enableStylePresets = false,
  contained,
  className,
}: AIImageGenerationTemplateProps = {}) {
  const [input, setInput] = useState("");
  const [prompt, setPrompt] = useState(autoRun && !onGenerate ? examplePrompt : "");
  const [busy, setBusy] = useState(autoRun && !onGenerate);
  const [result, setResult] = useState<ImageGenerationResult | null>(null);
  const [seconds, setSeconds] = useState(4);
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    const timer = setTimeout(() => setMounted(true), 1000);
    return () => clearTimeout(timer);
  }, []);
  const [run, setRun] = useState(0);
  const [tab, setTab] = useState("gallery");
  const [style, setStyle] = useState("Editorial");
  const [query, setQuery] = useState("");
  const [images, setImages] = useState<GalleryImage[]>(gallery);
  const [opened, setOpened] = useState<GalleryImage | null>(null);
  const [error, setError] = useState("");
  const controller = useRef<AbortController | null>(null);
  const generation = useRef(0);
  const reduced = useReducedMotion();
  const cancel = () => {
    generation.current += 1;
    controller.current?.abort();
    setBusy(false);
  };
  useEffect(() => () => controller.current?.abort(), []);
  const complete = useCallback((image: ImageGenerationResult, completedPrompt: string) => {
    const resolvedImage = { ...image, alt: image.alt ?? completedPrompt };
    setResult(resolvedImage);
    setSeconds(0);
    setBusy(false);
    setImages((old) => [
      { ...resolvedImage, src: image.gallerySrc ?? image.src },
      ...old.filter((item) => item.src !== (image.gallerySrc ?? image.src)),
    ]);
  }, []);
  useEffect(() => {
    if (!busy || onGenerate || !mounted) return;
    let active = true;
    const start = performance.now();
    const interval = setInterval(() => {
      if (active && generation.current === run)
        setSeconds(Math.max(0, 4 - Math.floor((performance.now() - start) / 1000)));
    }, 200);
    const timeout = setTimeout(() => {
      if (active && generation.current === run) complete(exampleResult, prompt);
    }, 4000);
    return () => {
      active = false;
      clearInterval(interval);
      clearTimeout(timeout);
    };
  }, [busy, onGenerate, run, prompt, complete, exampleResult, mounted]);
  const reset = () => {
    cancel();
    setPrompt("");
    setInput("");
    setResult(null);
    setError("");
    setOpened(null);
  };
  const generate = async (value: string) => {
    const next = value.trim();
    if (!next) return;
    cancel();
    const id = generation.current;
    const abort = new AbortController();
    controller.current = abort;
    setPrompt(next);
    setInput("");
    setResult(null);
    setError("");
    setSeconds(4);
    setRun(id);
    setBusy(true);
    if (onGenerate) {
      try {
        const image = await onGenerate(next, { signal: abort.signal, style });
        if (generation.current === id && !abort.signal.aborted) complete(image, next);
      } catch (cause) {
        if (generation.current !== id || abort.signal.aborted) return;
        setBusy(false);
        setError(cause instanceof Error ? cause.message : "Image generation failed. Try again.");
      }
    }
  };
  const visible = images.filter((item) => item.alt.toLowerCase().includes(query.toLowerCase()));
  const completed =
    result && visible[0]?.src === (result.gallerySrc ?? result.src) ? visible[0] : null;
  const remaining = completed ? visible.slice(1) : visible;
  const columnSize = Math.ceil(remaining.length / 3);
  const columns = Array.from({ length: 3 }, (_, column) => [
    ...(column === 0 && completed ? [completed] : []),
    ...remaining.slice(column * columnSize, (column + 1) * columnSize),
  ]);
  const panel = (
    <>
      <div className="flex h-[30px] w-full shrink-0 items-center justify-between">
        <PillTabList aria-label="Panel view">
          {[
            { id: "gallery", label: "Gallery", Icon: RiGalleryLine },
            { id: "styles", label: "Styles", Icon: RiSparklingLine },
          ].map(({ id, label, Icon }) => (
            <PillTab
              key={id}
              onSelect={() => setTab(id)}
              isSelected={tab === id}
              icon={Icon}
              className={id === "gallery" ? "[&_svg]:size-[18px]" : undefined}
            >
              {label}
            </PillTab>
          ))}
        </PillTabList>
        <WorkspacePanelActions
          onNew={onGenerate || workspace?.navigationActions ? reset : () => {}}
          newLabel="Start a new image"
          newIcon={RiImageAddLine}
        />
      </div>
      {tab === "styles" ? (
        enableStylePresets ? (
          <div className="min-h-0 grid grid-cols-2 gap-2 overflow-y-auto">
            {STYLES.map((name, index) => (
              <button
                type="button"
                key={name}
                onClick={() => setStyle(name)}
                aria-pressed={name === style}
                className={cx(
                  "group relative cursor-pointer overflow-hidden rounded-2xl border-2 text-left",
                  name === style ? "border-border-focus-ring" : "border-transparent",
                )}
              >
                <img
                  src={gallery[index]?.src ?? RESULT.src}
                  alt=""
                  className="aspect-[4/5] w-full object-cover transition-transform duration-300 group-hover:scale-105 motion-reduce:transform-none motion-reduce:transition-none"
                />
                <span className="absolute inset-x-2 bottom-2 flex items-center justify-between rounded-lg bg-background-full px-2 py-1 text-body-medium text-text-primary">
                  {name}
                  {name === style && <RiCheckLine className="size-4" />}
                </span>
              </button>
            ))}
          </div>
        ) : (
          <div className="flex min-h-0 w-full flex-1 items-center justify-center rounded-2lg bg-background-secondary-default">
            <span className="text-body-medium text-text-tertiary">Style presets</span>
          </div>
        )
      ) : (
        <>
          {enableGallerySearch && (
            <input
              aria-label="Search gallery"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search images"
              className="rounded-xl border border-border-button-default bg-background-primary-default px-3 py-2 text-body-regular text-text-primary outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
            />
          )}
          <div className="min-h-0 flex-1 overflow-y-auto">
            <div className="grid grid-cols-3 items-start gap-2">
              {columns.map((items, column) => (
                <div key={column} className="flex min-w-0 flex-col gap-2">
                  {items.map((item, index) => (
                    <figure
                      key={`${index}-${item.src}`}
                      className="group relative overflow-hidden rounded-[10px]"
                    >
                      <img
                        src={item.src}
                        alt={item.alt}
                        loading="lazy"
                        style={
                          item.aspectRatio
                            ? { aspectRatio: item.aspectRatio, objectFit: "cover" }
                            : undefined
                        }
                        className="block w-full"
                      />
                      <button
                        type="button"
                        aria-label={`Enlarge ${item.alt}`}
                        aria-expanded={opened?.src === item.src}
                        onClick={() => setOpened(item)}
                        className="absolute inset-0 cursor-zoom-in outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring"
                      />
                      <div className="pointer-events-none absolute inset-0 flex flex-col justify-between bg-linear-to-b from-neutral-950/40 via-transparent to-neutral-950/55 p-1.5 opacity-0 transition-opacity duration-200 ease-out group-hover:opacity-100 group-focus-within:opacity-100">
                        <span className="pointer-events-auto flex justify-end gap-1">
                          <a
                            href={item.src}
                            download
                            aria-label={`Download ${item.alt}`}
                            className="flex cursor-pointer items-center rounded-md bg-neutral-950/45 p-1 backdrop-blur-sm transition-colors hover:bg-neutral-950/65"
                          >
                            <RiDownloadLine className="size-3.5 text-white" />
                          </a>
                          <button
                            type="button"
                            aria-label={`More actions for ${item.alt}`}
                            className="flex cursor-pointer items-center rounded-md bg-neutral-950/45 p-1 backdrop-blur-sm transition-colors hover:bg-neutral-950/65"
                          >
                            <RiMore2Line className="size-3.5 text-white" />
                          </button>
                        </span>
                        <figcaption className="line-clamp-2 px-0.5 text-body-2-regular text-white">
                          {item.alt}
                        </figcaption>
                      </div>
                    </figure>
                  ))}
                </div>
              ))}
            </div>
            {visible.length === 0 && (
              <p className="p-4 text-body-regular text-text-secondary">
                No images match your search.
              </p>
            )}
          </div>
        </>
      )}
    </>
  );
  return (
    <>
      <AgentWorkspace
        {...workspace}
        navigationActions={!!onGenerate}
        kind="image"
        input={input}
        onInputChange={setInput}
        onSubmit={(value) => void generate(value)}
        onStop={cancel}
        onNew={reset}
        busy={!!onGenerate && busy}
        thinking={busy && mounted}
        contained={contained}
        className={className}
        panel={panel}
      >
        {!prompt && (
          <div className="flex flex-1 flex-col justify-center py-20 text-center">
            <h1 className="text-title-2-medium text-text-primary">Bring your ideas to life.</h1>
            <p className="pt-2 text-body-regular text-text-secondary">
              Describe an image to get started.
            </p>
          </div>
        )}
        {prompt && (
          <motion.p
            key={prompt}
            initial={run === 0 || reduced ? false : { opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: reduced ? 0 : 0.3 }}
            className={cx(workspaceUserMessageClasses, "text-body-regular text-text-primary")}
          >
            {prompt}
          </motion.p>
        )}
        {((busy && (mounted || !!onGenerate)) || result) && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.4, ease: "easeOut" }}
            className="flex w-full flex-col items-start gap-2"
          >
            <motion.div
              initial={{ opacity: 0, filter: "blur(6px)", y: 6 }}
              animate={{ opacity: 1, filter: "blur(0px)", y: 0 }}
              transition={{ duration: 0.5, ease: [0.25, 0.1, 0.25, 1] }}
            >
              <div className="flex w-[200px] items-baseline text-body-regular text-text-primary">
                {result ? "Image generated" : ""}
              </div>
            </motion.div>
            <GeneratedImageCard
              key={run}
              busy={busy}
              seconds={onGenerate ? null : seconds}
              animateEntry
              result={result}
              preview={onGenerate ? undefined : exampleResult}
            />
            {result && (
              <ConversationFeedback
                text={prompt}
                variant="subtle"
                showRetry={!!onGenerate}
                onRetry={() => void generate(prompt)}
              />
            )}
          </motion.div>
        )}
        {error && (
          <p role="alert" className="text-body-regular text-status-rose-text">
            {error}
          </p>
        )}
        {prompt && !busy && !result && !error && (
          <p role="status" className="text-body-regular text-text-secondary">
            Generation stopped.
          </p>
        )}
        {prompt && !busy && !result && (
          <Button
            size="small"
            variant="secondary"
            className="self-start"
            onClick={() => void generate(prompt)}
          >
            Try again
          </Button>
        )}
      </AgentWorkspace>
      <ModalOverlay
        isOpen={!!opened}
        onOpenChange={(open) => {
          if (!open) setOpened(null);
        }}
        isDismissable
        className="fixed inset-0 z-50 flex items-center justify-center bg-background-modal-overlay p-4 backdrop-blur-lg"
      >
        <Modal className="max-h-[95dvh] max-w-4xl overflow-auto rounded-3xl border border-border-button-default bg-background-full p-3 shadow-dropdown">
          <Dialog className="outline-none">
            <div className="mb-3 flex items-center justify-between gap-4">
              <Heading slot="title" className="truncate text-body-medium text-text-primary">
                {opened?.alt}
              </Heading>
              <IconButton
                icon={RiCloseLine}
                size="small"
                aria-label="Close image"
                onClick={() => setOpened(null)}
              />
            </div>
            {opened && (
              <img
                src={opened.src}
                alt={opened.alt}
                className="max-h-[75dvh] w-full rounded-xl object-contain"
              />
            )}
            <div className="mt-3 flex justify-end">
              <a
                href={opened?.src}
                download
                className="flex items-center gap-1 rounded-full bg-button-primary px-3 py-2 text-body-medium text-button-primary-foreground"
              >
                <RiDownloadLine className="size-4" />
                Download image
              </a>
            </div>
          </Dialog>
        </Modal>
      </ModalOverlay>
    </>
  );
}
